function Profile() {
  return (
    <div style={{ padding: "12px" }}>
      <h2>My Profile</h2>

      {/* 프로필 */}
      <div style={{ display: "flex", gap: "10px", alignItems: "center" }}>
        <div style={{
          width: "60px",
          height: "60px",
          borderRadius: "50%",
          background: "#ccc"
        }} />
        <div>
          <h4>김수연</h4>
          <p>팔로워 10 · 팔로잉 5</p>
        </div>
      </div>

      {/* 책 피드 */}
      <h3 style={{ marginTop: "20px" }}>내 독후감 기록</h3>

      <div style={{
        display: "grid",
        gridTemplateColumns: "repeat(3, 1fr)",
        gap: "8px"
      }}>
        <div style={{ height: "100px", background: "#eee" }} />
        <div style={{ height: "100px", background: "#eee" }} />
        <div style={{ height: "100px", background: "#eee" }} />
      </div>
    </div>
  );
}

export default Profile;
